Method.Implementation:

	#dim status as %Status
	set status = $$$OK
	$$$TRACE("Inside IHC.ITF.Operation.IhcHieCdrDemogrUpdates OnMessage method..")


	try {	

		$$$TRACE("Hl7 Msg : " _ pRequest.RawContent)	
		$$$TRACE("Log Dir : " _ ..LogDirectory)		
		set objCdrUpdate = ##class(org.ihc.itf.cdr.CdrMmiAddsUpdates).%New(..JavaGateway,..LogDirectory _"/" _$$$JobConfigName _".log", ..LogFlag)
		$$$TRACE("Object name: " _ objCdrUpdate.%ClassName(1))
		set isUpdate = objCdrUpdate.CdrMmiAddsUpdatesCall(pRequest.RawContent, "1")

		if (isUpdate="1"){
			$$$TRACE(" ********* Cdr Update Successfull!! **********"_isUpdate)
		}else{
			$$$TRACE(" ********* Failed to Update CDR!!! **********"_isUpdate)
			if (isUpdate["No record found"){
				Set status = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("Out-Cdr-Demogr-Gateway-IHCHIEUPDATES",isUpdate_". New adds are not allowed in CDR. Skipping the record.")
			}
		}
	} catch err {	
	        set sysText = ""
 			if (err.%IsA("%Exception.SystemException")){
	 			set sysText = " SystemException: " _err.AsSystemError()_ "; "	 
 			}
 			If $GET(%objlasterror) '=""{
 				set sysText = sysText _ "ErrorText: " _ $System.Status.GetErrorText(%objlasterror) _ "; "	 
 			}
			Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Demogr-Gateway-IHCHIEUPDATES",sysText)
	}	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status
